681:             info->list[i].user_info = user_info;
682:             info->list[i].real_info = real_info;
683:             Py_INCREF(callback);
684:             Py_INCREF(user_info);
685:             Py_INCREF(real_info);
686: 
687: #if PY_VERSION_HEX >= 0x030d0000
