  "summary": "pyobjc-framework-Quartz 是 PyObjC 项目中针对 macOS Quartz 图形框架群的 Python 桥接绑定，通过 Objective-C 原生扩展将 Apple 的多套底层图形/媒体框架暴露为 Python API，使 Python 开发者可直接在 macOS 上调用 CoreGraphics 二维绘图、CoreVideo 数字视频处理、ImageIO 图像读写、PDFKit PDF 文档操作、QuartzCore 图像处理与视频滤镜、ImageKit 图像浏览视图、QuickLookUI 文件预览整合等全部原生能力。该库是 PyObjC 生态的组件之一，主要面向需要在 Python 中利用 macOS 原生图形栈的桌面应用开发者与自动化脚本编写者。",
  "categories": [
    {
      "name": "二维图形绘制 (CoreGraphics)",
      "description": "封装 Apple CoreGraphics (Quartz 2D) 框架，提供 PDF 模型下的矢量绘图、位图上下文、路径操作、渐变与图案填充、文字排版、颜色空间管理、显示与窗口列表等底层 2D 图形能力",
      "evidence": ["Modules/_coregraphics.m", "Modules/_CoreGraphics_inlines.m", "Modules/_callbacks.m", "Modules/_sortandmap.m", "Lib/Quartz/CoreGraphics/__init__.py"]
    },
    {
      "name": "图像与照片处理 (QuartzCore / CoreImage)",
      "description": "封装 CoreImage 图像滤镜处理管线与 QuartzCore 图像组合/动画能力，提供 CIFilter 滤镜应用、图像分析、图层合成等高级图像处理功能",
      "evidence": ["Modules/_quartzcore.m", "Modules/_CoreImage_protocols.m", "Modules/_QuartzCore_protocols.m", "Lib/Quartz/QuartzCore/__init__.py"]
    },
    {
      "name": "图像格式读写 (ImageIO)",
      "description": "封装 ImageIO 框架，提供对 PNG、JPEG、TIFF、GIF、HEIF 等多种图像格式的读取、写入、元数据提取和渐进式加载支持",
      "evidence": ["Lib/Quartz/ImageIO/", "Lib/Quartz/__init__.py"]
    },
    {
      "name": "数字视频处理 (CoreVideo)",
      "description": "封装 CoreVideo 框架，提供视频像素缓冲区的创建与管理、视频帧的时间戳处理、帧格式转换等低级别视频数据处理能力",
      "evidence": ["Modules/_CVPixelBuffer.m", "Lib/Quartz/CoreVideo/"]
    },
    {
      "name": "PDF 文档操作 (PDFKit)",
      "description": "封装 PDFKit 框架，提供 PDF 文档的读取、渲染、页面导航、批注处理、表单填写、文本选择与搜索等完整的 PDF 文件操作能力",
      "evidence": ["Modules/_PDFKit.m", "Modules/_PDFKit_protocols.m", "Lib/Quartz/PDFKit/"]
    },
    {
      "name": "图像浏览与选取 (ImageKit)",
      "description": "封装 ImageKit 框架，提供类似 iPhoto 的图像浏览器视图控件和图像捕获设备交互（扫描仪、摄像头）功能",
      "evidence": ["Modules/_imagekit.m", "Modules/_ImageKit_protocols.m", "Lib/Quartz/ImageKit/"]
    },
    {
      "name": "Quartz Composer 组合",
      "description": "封装 QuartzComposer 框架，支持加载、播放和交互操作 Quartz Composer 创建的图形合成文件（.qtz）",
      "evidence": ["Lib/Quartz/QuartzComposer/", "Lib/Quartz/__init__.py"]
    },
    {
      "name": "图像滤镜效果 (QuartzFilters)",
      "description": "封装 QuartzFilters 框架，提供 CoreGraphics 上下文内的图像滤镜效果应用能力",
      "evidence": ["Lib/Quartz/QuartzFilters/", "Lib/Quartz/__init__.py"]
    },
    {
      "name": "文件快速预览 (QuickLookUI)",
      "description": "封装 QuickLookUI 框架，提供 macOS Finder 快速预览功能的 UI 集成，支持在应用中嵌入文件预览面板",
      "evidence": ["Modules/_QuickLookUI.m", "Modules/_QuickLookUI_protocols.m", "Lib/Quartz/QuickLookUI/"]
    }
  ],
